CREATE TABLE public.post_chat_pairs (post_id uuid NOT NULL REFERENCES public.posts(id) ON DELETE CASCADE, member_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, owner_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(post_id,member_id), CHECK(member_id<>owner_id));
GRANT SELECT ON public.post_chat_pairs TO authenticated;
GRANT ALL ON public.post_chat_pairs TO service_role;
ALTER TABLE public.post_chat_pairs ENABLE ROW LEVEL SECURITY;
CREATE POLICY pair_participants ON public.post_chat_pairs FOR SELECT TO authenticated USING(auth.uid() IN(member_id,owner_id));
INSERT INTO public.post_chat_pairs(post_id,member_id,owner_id) SELECT DISTINCT m.post_id,CASE WHEN m.sender_id=p.user_id THEN m.receiver_id ELSE m.sender_id END,p.user_id FROM public.messages m JOIN public.posts p ON p.id=m.post_id WHERE p.user_id IN(m.sender_id,m.receiver_id) AND m.sender_id<>m.receiver_id ON CONFLICT DO NOTHING;
ALTER TABLE public.messages ADD COLUMN chat_phone text NOT NULL DEFAULT '', ADD COLUMN image_path text NOT NULL DEFAULT '';
CREATE OR REPLACE FUNCTION public.can_post_chat(_post uuid,_other uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND auth.uid()<>_other AND public.account_allowed(auth.uid()) AND public.account_allowed(_other) AND CASE WHEN _post IS NULL THEN _other=public.support_admin_id() OR EXISTS(SELECT 1 FROM public.messages WHERE post_id IS NULL AND ((sender_id=auth.uid() AND receiver_id=_other) OR (receiver_id=auth.uid() AND sender_id=_other))) ELSE EXISTS(SELECT 1 FROM public.post_chat_pairs WHERE post_id=_post AND ((member_id=auth.uid() AND owner_id=_other) OR (owner_id=auth.uid() AND member_id=_other))) END $$;
REVOKE ALL ON FUNCTION public.can_post_chat(uuid,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.can_post_chat(uuid,uuid) TO authenticated,service_role;
CREATE POLICY chat_relationship_required ON public.messages AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(sender_id=auth.uid() AND public.can_post_chat(post_id,receiver_id));
CREATE OR REPLACE FUNCTION public.guard_chat_attachment() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.chat_phone<>'' AND NEW.chat_phone !~ '^[6-9][0-9]{9}$' THEN RAISE EXCEPTION 'INVALID_CHAT_PHONE'; END IF; IF NEW.image_path<>'' AND NEW.image_path NOT LIKE NEW.sender_id::text||'/%' THEN RAISE EXCEPTION 'INVALID_CHAT_IMAGE'; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_chat_attachment BEFORE INSERT ON public.messages FOR EACH ROW EXECUTE FUNCTION public.guard_chat_attachment();
CREATE POLICY chat_images_participants ON storage.objects FOR SELECT TO authenticated USING(bucket_id='chat-images' AND EXISTS(SELECT 1 FROM public.messages m WHERE m.image_path=name AND auth.uid() IN(m.sender_id,m.receiver_id)));
CREATE OR REPLACE FUNCTION public.guard_new_match_notifications() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE mode text:=current_setting('app.bell_notice',true); BEGIN IF NEW.post_id IS NULL AND NEW.matched_post_id IS NULL THEN RETURN NEW; END IF; IF mode IS NULL OR mode NOT IN('owner','interest') THEN RETURN NULL; END IF; IF EXISTS(SELECT 1 FROM public.posts WHERE id IN(NEW.post_id,NEW.matched_post_id) AND (visible_after>now() OR job_expires_at<=now() OR status<>'active' OR NOT public.account_allowed(user_id))) THEN RETURN NULL; END IF; IF mode='owner' AND NOT public.post_alert_eligible(NEW.user_id) THEN RETURN NULL; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.notify_matches(_post_id uuid) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.posts; m record; n integer:=0; notice uuid; BEGIN IF auth.uid() IS NULL OR NOT public.account_allowed(auth.uid()) THEN RAISE EXCEPTION 'SIGN_IN_REQUIRED'; END IF; SELECT * INTO p FROM public.posts WHERE id=_post_id AND user_id=auth.uid() AND status='active' AND (visible_after IS NULL OR visible_after<=now()) AND (job_expires_at IS NULL OR job_expires_at>now()); IF p.id IS NULL THEN RAISE EXCEPTION 'OWN_VISIBLE_POST_REQUIRED'; END IF; PERFORM set_config('app.bell_notice','owner',true); FOR m IN SELECT DISTINCT ON(user_id) candidate.* FROM public.posts candidate WHERE public.posts_match_area(p,candidate) AND (visible_after IS NULL OR visible_after<=now()) AND (job_expires_at IS NULL OR job_expires_at>now()) ORDER BY user_id,created_at DESC LOOP IF n>=3 THEN EXIT; END IF; PERFORM 1 FROM public.profiles WHERE id=m.user_id FOR UPDATE; IF public.can_notify(m.user_id) AND NOT EXISTS(SELECT 1 FROM public.notifications WHERE user_id=m.user_id AND matched_post_id=p.id AND created_at>now()-interval '5 minutes') THEN notice:=NULL; INSERT INTO public.notifications(user_id,post_id,matched_post_id,message) VALUES(m.user_id,m.id,p.id,'గంట కొట్టారు · Bell: '||CASE WHEN p.module='vehicle' THEN coalesce(p.vehicle_type,'వాహనం') ELSE coalesce(p.skill,'ఉద్యోగం') END) RETURNING id INTO notice; IF notice IS NOT NULL THEN n:=n+1; END IF; END IF; END LOOP; PERFORM set_config('app.bell_notice','',true); RETURN n; END $$;
CREATE OR REPLACE FUNCTION public.ring_post(_post_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.posts; caller uuid:=auth.uid(); BEGIN IF caller IS NULL OR NOT public.account_allowed(caller) THEN RAISE EXCEPTION 'SIGN_IN_REQUIRED'; END IF; SELECT * INTO p FROM public.posts WHERE id=_post_id AND status='active' AND (visible_after IS NULL OR visible_after<=now()) AND (job_expires_at IS NULL OR job_expires_at>now()) AND public.account_allowed(user_id); IF p.id IS NULL OR p.user_id=caller THEN RAISE EXCEPTION 'POST_UNAVAILABLE'; END IF; INSERT INTO public.post_chat_pairs(post_id,member_id,owner_id) VALUES(p.id,caller,p.user_id) ON CONFLICT DO NOTHING; PERFORM set_config('app.bell_notice','interest',true); PERFORM 1 FROM public.profiles WHERE id=p.user_id FOR UPDATE; IF public.can_notify(p.user_id) THEN INSERT INTO public.notifications(user_id,post_id,message) VALUES(p.user_id,p.id,'మీ ప్రకటనపై సమాచారం కోరారు · Someone rang your post bell'); END IF; IF NOT EXISTS(SELECT 1 FROM public.messages WHERE post_id=p.id AND sender_id=caller AND receiver_id=p.user_id) THEN INSERT INTO public.messages(sender_id,receiver_id,post_id,body) VALUES(caller,p.user_id,p.id,'మీ ప్రకటనపై సమాచారం కావాలి · Interested in your post'); END IF; PERFORM set_config('app.bell_notice','',true); RETURN p.user_id; END $$;
REVOKE ALL ON FUNCTION public.notify_matches(uuid),public.ring_post(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.notify_matches(uuid),public.ring_post(uuid) TO authenticated;
COMMENT ON TABLE public.post_chat_pairs IS 'Bell-created private participant pairs; historical owner/member conversations retained. Post-linked automatic notices are suppressed by the central guard.';